//! Oracle vectors for the string builtins (`twig_value::builtins::string`): PHP 8.5.13 results,
//! diagnostics and exceptions for the calls in `tests/vectors/string/*.json`, generated by the PHP
//! scripts next to them (the case format is described in `calls.inc.php`).
//!
//! Regenerate with the Docker oracle (`research/php-oracle`, image `twig-oracle:3.31.1`):
//!
//! ```text
//! cd crates/twig-value/tests/vectors
//! for t in basic trim split replace markup html url iconv iconv_charsets iconv_sweep; do
//!   MSYS_NO_PATHCONV=1 docker run --rm -v "$(pwd -W 2>/dev/null || pwd):/t" twig-oracle:3.31.1 \
//!       php /t/string/$t.gen.php > string/$t.json
//! done
//! ```

mod support;

use serde_json::Value as Json;
use support::values::{res_json, typed_value};
use support::{Mismatches, diag_list, json_diags, load, s};
use twig_value::builtins::string as st;
use twig_value::object::ArrayObject;
use twig_value::{Array, Diagnostic, PhpResult, Value};

fn string(r: PhpResult<twig_value::PhpString>) -> PhpResult<Value> {
    r.map(Value::String)
}

fn int(r: PhpResult<i64>) -> PhpResult<Value> {
    r.map(Value::Int)
}

fn boolean(r: PhpResult<bool>) -> PhpResult<Value> {
    r.map(Value::Bool)
}

fn int_or_false(r: PhpResult<Option<i64>>) -> PhpResult<Value> {
    r.map(|o| o.map_or(Value::Bool(false), Value::Int))
}

/// The Rust counterpart of each entry of `calls()` in `calls.inc.php`.
fn call(f: &str, a: &[Value], d: &mut Vec<Diagnostic>) -> PhpResult<Value> {
    let o = |i: usize| a.get(i);
    match f {
        "strlen" => int(st::strlen(&a[0], d)),
        "substr2" => string(st::substr(&a[0], &a[1], None, d)),
        "substr3" => string(st::substr(&a[0], &a[1], o(2), d)),
        "strpos2" => int_or_false(st::strpos(&a[0], &a[1], None, d)),
        "strpos3" => int_or_false(st::strpos(&a[0], &a[1], o(2), d)),
        "strrpos2" => int_or_false(st::strrpos(&a[0], &a[1], None, d)),
        "strrpos3" => int_or_false(st::strrpos(&a[0], &a[1], o(2), d)),
        "substr_count2" => int(st::substr_count(&a[0], &a[1], None, None, d)),
        "substr_count3" => int(st::substr_count(&a[0], &a[1], o(2), None, d)),
        "substr_count4" => int(st::substr_count(&a[0], &a[1], o(2), o(3), d)),
        "str_contains" => boolean(st::str_contains(&a[0], &a[1], d)),
        "str_starts_with" => boolean(st::str_starts_with(&a[0], &a[1], d)),
        "str_ends_with" => boolean(st::str_ends_with(&a[0], &a[1], d)),
        "strtolower" => string(st::strtolower(&a[0], d)),
        "strtoupper" => string(st::strtoupper(&a[0], d)),
        "ucfirst" => string(st::ucfirst(&a[0], d)),
        "lcfirst" => string(st::lcfirst(&a[0], d)),
        "ucwords1" => string(st::ucwords(&a[0], None, d)),
        "ucwords2" => string(st::ucwords(&a[0], o(1), d)),
        "strcmp" => int(st::strcmp(&a[0], &a[1], d)),
        "strcasecmp" => int(st::strcasecmp(&a[0], &a[1], d)),
        "strncasecmp" => int(st::strncasecmp(&a[0], &a[1], &a[2], d)),
        "ord" => int(st::ord(&a[0], d)),
        "chr" => string(st::chr(&a[0], d)),
        "str_repeat" => string(st::str_repeat(&a[0], &a[1], d)),
        "trim1" => string(st::trim(&a[0], None, d)),
        "trim2" => string(st::trim(&a[0], o(1), d)),
        "ltrim1" => string(st::ltrim(&a[0], None, d)),
        "ltrim2" => string(st::ltrim(&a[0], o(1), d)),
        "rtrim1" => string(st::rtrim(&a[0], None, d)),
        "rtrim2" => string(st::rtrim(&a[0], o(1), d)),
        "explode2" => st::explode(&a[0], &a[1], None, d).map(Value::Array),
        "explode3" => st::explode(&a[0], &a[1], o(2), d).map(Value::Array),
        "implode1" => string(st::implode_frameless(&a[0], None, d)),
        "implode2" => string(st::implode_frameless(&a[0], o(1), d)),
        "implode1_dyn" => string(st::implode(&a[0], None, d)),
        "implode2_dyn" => string(st::implode(&a[0], o(1), d)),
        "strtr2" => string(st::strtr(&a[0], &a[1], None, d)),
        "strtr3" => string(st::strtr(&a[0], &a[1], o(2), d)),
        "str_replace" => st::str_replace(&a[0], &a[1], &a[2], d),
        "str_replace_count" => st::str_replace_count(&a[0], &a[1], &a[2], d)
            .map(|(r, n)| Value::Array(Array::from_values([r, Value::Int(n)]))),
        "nl2br1" => string(st::nl2br(&a[0], None, d)),
        "nl2br2" => string(st::nl2br(&a[0], o(1), d)),
        "strip_tags1" => string(st::strip_tags(&a[0], None, d)),
        "strip_tags2" => string(st::strip_tags(&a[0], o(1), d)),
        "htmlspecialchars1" => string(st::htmlspecialchars(&a[0], None, None, None, d)),
        "htmlspecialchars2" => string(st::htmlspecialchars(&a[0], o(1), None, None, d)),
        "htmlspecialchars3" => string(st::htmlspecialchars(&a[0], o(1), o(2), None, d)),
        "htmlspecialchars4" => string(st::htmlspecialchars(&a[0], o(1), o(2), o(3), d)),
        "rawurlencode" => string(st::rawurlencode(&a[0], d)),
        "urlencode" => string(st::urlencode(&a[0], d)),
        "http_build_query1" => string(st::http_build_query(&a[0], None, None, None, d)),
        "http_build_query2" => string(st::http_build_query(&a[0], o(1), None, None, d)),
        "http_build_query3" => string(st::http_build_query(&a[0], o(1), o(2), None, d)),
        "http_build_query4" => string(st::http_build_query(&a[0], o(1), o(2), o(3), d)),
        "levenshtein2" => int(st::levenshtein(&a[0], &a[1], None, None, None, d)),
        "levenshtein5" => int(st::levenshtein(&a[0], &a[1], o(2), o(3), o(4), d)),
        "ctype_alnum" => boolean(st::ctype_alnum(&a[0], d)),
        "ctype_alpha" => boolean(st::ctype_alpha(&a[0], d)),
        "ctype_cntrl" => boolean(st::ctype_cntrl(&a[0], d)),
        "ctype_digit" => boolean(st::ctype_digit(&a[0], d)),
        "ctype_lower" => boolean(st::ctype_lower(&a[0], d)),
        "ctype_graph" => boolean(st::ctype_graph(&a[0], d)),
        "ctype_print" => boolean(st::ctype_print(&a[0], d)),
        "ctype_punct" => boolean(st::ctype_punct(&a[0], d)),
        "ctype_space" => boolean(st::ctype_space(&a[0], d)),
        "ctype_upper" => boolean(st::ctype_upper(&a[0], d)),
        "ctype_xdigit" => boolean(st::ctype_xdigit(&a[0], d)),
        "iconv" => {
            st::iconv(&a[0], &a[1], &a[2], d).map(|r| r.map_or(Value::Bool(false), Value::String))
        }
        other => panic!("no Rust counterpart for call {other}"),
    }
}

/// Runs every case of `string/<file>` and compares result and diagnostics with PHP's.
fn run(file: &'static str) {
    let v = load(&format!("string/{file}"));
    let mut m = Mismatches::new(file);
    for case in v["cases"].as_array().expect("cases") {
        let f = s(&case["f"]);
        let args: Vec<Value> = case["a"]
            .as_array()
            .expect("args")
            .iter()
            .map(decode)
            .collect();
        let mut d: Vec<Diagnostic> = Vec::new();
        let r = call(f, &args, &mut d);
        m.check(
            || {
                let mut a = case["a"].to_string();
                a.truncate(300);
                format!("{f}({a})")
            },
            (res_json(&r), diag_list(&d)),
            (case["r"].clone(), json_diags(&case["d"])),
        );
    }
    m.finish();
}

